local strings = {}
for i, lang in ipairs(LANGS) do
    local s = {}
    for key, list in pairs(T) do s[key] = list[i] end
    strings[lang] = s
end

local active = strings.enUS
ns.language = "enUS"
ns.L = setmetatable({}, {
    __index = function(_, k)
        return active[k] or strings.enUS[k] or k
    end,
})

function ns.ResolveLanguage(setting)
    if setting and strings[setting] then return setting end
    local client = GetLocale and GetLocale() or "enUS"
    client = CLIENT_LANGUAGE[client] or client
    return strings[client] and client or "enUS"
end

function ns.SetLanguage(setting)
    ns.language = ns.ResolveLanguage(setting)
    active = strings[ns.language]
end

-- The client's own font covers its language; another language may need another font.
function ns.FontFile()
    local client = GetLocale and GetLocale() or "enUS"
    client = CLIENT_LANGUAGE[client] or client
    if ns.language == client then return STANDARD_TEXT_FONT end
    return FONT_FILES[ns.language] or STANDARD_TEXT_FONT
end
